{"path": "/tmp/sv-7fbf26e06e114fd08e2cc2c05b7a2e16/Components/Chat/MessageInput.razor", "file_text": "<div class="message-input">
    <textarea class="form-control" rows="2"
              placeholder="@Placeholder"
              @bind="_text"
              @onkeydown="HandleKeyDown"></textarea>
    <button class="btn btn-primary send-btn" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(_text)">
        @ButtonText
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string _text = string.Empty;

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(_text)) return;
        var msg = _text.Trim();
        _text = string.Empty;
        await OnSend.InvokeAsync(msg);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }
}
"}

