@using sv_7fbf26e06e114fd08e2cc2c05b7a2e16.Services

<button class="channel-item @(IsActive ? "active" : "")" @onclick="OnSelected">
    <div class="channel-header">
        <span class="channel-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="badge bg-primary rounded-pill">@Channel.UnreadCount</span>
        }
    </div>
    @if (!string.IsNullOrWhiteSpace(Channel.Description))
    {
        <div class="channel-description text-muted">@TruncateDescription(Channel.Description)</div>
    }
</button>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback OnSelected { get; set; }

    private string TruncateDescription(string desc) =>
        desc.Length > 40 ? desc[..40] + "…" : desc;
}

