toolArgs.file_text:
@using sv_7fbf26e06e114fd08e2cc2c05b7a2e16.Services
@inject IJSRuntime JS

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="area-header">
            <h5># @Channel.Name</h5>
            <span class="text-muted">@Channel.Description</span>
        </div>

        <div class="message-list" @ref="_scrollContainer" @onscroll="HandleScroll">
            @if (IsLoading)
            {
                <div class="text-center py-2">
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                    <span class="ms-2 text-muted">Loading…</span>
                </div>
            }
            @foreach (var msg in Messages)
            {
                <MessageBubble Message="msg"
                               ReplyCount="GetReplyCount(msg.Id)"
                               OnReply="OnReply"
                               OnReact="OnReact"
                               OnViewThread="OnViewThread" />
            }
            <div @ref="_scrollAnchor"></div>
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonText="Send"
                      OnSend="OnSend" />
    }
    else
    {
        <div class="empty-state">
            <p class="text-muted">Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSend { get; set; }
    [Parameter] public EventCallback<int> OnReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<int> OnViewThread { get; set; }
    [Parameter] public bool ShouldScrollToBottom { get; set; }

    private ElementReference _scrollContainer;
    private ElementReference _scrollAnchor;
    private bool _shouldScroll;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    protected override void OnParametersSet()
    {
        if (ShouldScrollToBottom)
            _shouldScroll = true;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_shouldScroll)
        {
            _shouldScroll = false;
            try
            {
                await JS.InvokeVoidAsync("eval",
                    "document.querySelector('[data-scroll-anchor]')?.scrollIntoView()");
            }
            catch { /* SSR or disconnected */ }
        }
    }

    private async Task HandleScroll()
    {
        try
        {
            var scrollTop = await JS.InvokeAsync<double>("eval",
                "document.querySelector('.message-list')?.scrollTop ?? 1");
            if (scrollTop < 50 && !IsLoading)
            {
                await OnLoadMore.InvokeAsync();
            }
        }
        catch { /* ignore */ }
    }
}

