.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #dee2e6;
    flex-shrink: 0;
}

.area-header h5 {
    margin: 0;
    font-weight: 700;
}

.area-header .text-muted {
    font-size: 0.85rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
