arguments.file_text:
@page "/chat"
@using sv_7fbf26e06e114fd08e2cc2c05b7a2e16.Components.Chat
@using sv_7fbf26e06e114fd08e2cc2c05b7a2e16.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadOpen ? "with-thread" : "")">
        <MessageArea Channel="_activeChannel"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     IsLoading="_loadingMessages"
                     ShouldScrollToBottom="_scrollToBottom"
                     OnLoadMore="LoadOlderMessages"
                     OnSend="SendMessage"
                     OnReply="OpenThread"
                     OnReact="AddReaction"
                     OnViewThread="OpenThread" />
    </div>

    @if (_threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         IsLoading="_loadingThread"
                         OnSendReply="SendThreadReply"
                         OnClose="CloseThread" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = new();
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = new();
    private Dictionary<int, int> _threadReplyCounts = new();
    private bool _loadingMessages;
    private bool _scrollToBottom;

    // Thread state
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = new();
    private bool _loadingThread;

    // Pagination
    private const int PageSize = 30;
    private int _skip;
    private bool _hasMoreMessages = true;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (_activeChannelId == channelId) return;

        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages.Clear();
        _threadReplyCounts.Clear();
        _skip = 0;
        _hasMoreMessages = true;
        _scrollToBottom = true;

        CloseThread();
        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        if (!_hasMoreMessages || _activeChannelId is null) return;

        _loadingMessages = true;
        StateHasChanged();

        var batch = await ChatService.GetMessagesAsync(_activeChannelId.Value, _skip, PageSize);

        if (batch.Count < PageSize)
            _hasMoreMessages = false;

        // Prepend older messages
        _messages.InsertRange(0, batch);
        _skip += batch.Count;

        ComputeThreadReplyCounts();
        _loadingMessages = false;
    }

    private async Task LoadOlderMessages()
    {
        _scrollToBottom = false;
        await LoadMessages();
    }

    private void ComputeThreadReplyCounts()
    {
        _threadReplyCounts.Clear();
        foreach (var msg in _messages)
        {
            if (msg.ReplyToId is int rootId)
            {
                _threadReplyCounts.TryGetValue(rootId, out var count);
                _threadReplyCounts[rootId] = count + 1;
            }
        }
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, content, null);
        _messages.Add(msg);
        _skip++;
        _scrollToBottom = true;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadOpen = true;
        _loadingThread = true;
        StateHasChanged();

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _loadingThread = false;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannelId is null || _threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            _activeChannelId.Value, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count in main view
        _threadReplyCounts.TryGetValue(_threadRootMessage.Id, out var count);
        _threadReplyCounts[_threadRootMessage.Id] = count + 1;
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update
        var msgIdx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (msgIdx >= 0)
        {
            var msg = _messages[msgIdx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                if (!r.Users.Contains("You"))
                    reactions[existing] = r with { Users = [..r.Users, "You"] };
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[msgIdx] = msg with { Reactions = reactions };
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

